mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.vocaplan vocaplan,
  ttokssaemdb.member member

  AND vocaplan.memberid = member.memberid    

    AND vocaplan.branchid = #{session_branchid}


    AND (
      member.membername LIKE #{likeQuery}
    )

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberid, member.membername, vocaplan.vocalevel, (SELECT codename FROM cmm_code WHERE code = vocaplan.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocaplan.dayofweek, vocaplan.passrate, vocaplan.targetcount, vocaplan.stopyn, DATE_FORMAT(vocaplan.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.vocaplan vocaplan, ttokssaemdb.branch branch, ttokssaemdb.member member
AND vocaplan.branchid = branch.branchid AND vocaplan.memberid = member.memberid
AND vocaplan.branchid = #{session_branchid}
AND ( member.membername LIKE #{likeQuery} )
vocaplan.vocaplanid vocaplan.vocalevel vocaplan.passrate vocaplan.regdate DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}
